// The hand-built 3D models live in PACKS — one module per reference sheet
// (see order.js). A deck downloads only the packs holding the models its
// props use: packs.json (generated by tools/gen-model-index.mjs) says which
// pack holds which model. A pack registers its models when it is imported.
import index from './packs.json';
import { PACK_ORDER } from './order.js';
import { setPack } from './registry.js';

const modules = import.meta.glob(['./*.js', '!./index.js', '!./kit.js', '!./registry.js', '!./order.js']);
const pathOf = (pack) => `./${pack}.js`;
const known = Object.keys(modules).map((p) => p.slice(2, -3));
// registration order: the listed packs, then any new ones
const ORDER = [...PACK_ORDER.filter((p) => known.includes(p)), ...known.filter((p) => !PACK_ORDER.includes(p)).sort()];

const loading = new Map(); // pack → import promise

// One after another, in registration order — a later pack's model replaces
// an earlier one of the same name, whatever the network does.
async function loadPacks(packs, onProgress) {
  const wanted = ORDER.filter((p) => packs.has(p));
  let done = 0;
  for (const pack of wanted) {
    onProgress?.(done, wanted.length, pack);
    if (!loading.has(pack)) {
      setPack(pack);
      loading.set(pack, modules[pathOf(pack)]());
    }
    await loading.get(pack);
    done++;
  }
  onProgress?.(done, wanted.length);
  setPack(null);
}

// Load the packs that hold these models (names without a model are skipped —
// those objects show their flat sprite).
export function loadModelsFor(names, onProgress) {
  const packs = new Set();
  for (const n of names) if (index.models[n]) packs.add(index.models[n]);
  return loadPacks(packs, onProgress);
}

export function loadAllModels() {
  return loadPacks(new Set(ORDER));
}

export function loadedPacks() {
  return [...loading.keys()];
}
